import Foundation
import AppKit
import CoreGraphics
import Carbon
import ApplicationServices

/// macOS uygulamalarına pano ve sentetik klavye olayı üzerinden metin gönderen yönetici.
/// Hedef uygulamanın kendi metin alanı ve güvenlik politikası, gerçek yapıştırma
/// davranışını etkileyebileceği için sonuçlar "olay gönderildi" düzeyinde doğrulanır.
///
/// Pano Koruması:
/// - nspasteboard.org topluluk standardı `org.nspasteboard.TransientType` ve
///   `org.nspasteboard.AutoGeneratedType` bayrakları eklenerek Raycast, Maccy, Alfred
///   gibi pano yöneticilerinin geçmişe kaydetmesi önlenir.
/// - Geri yükleme aktifse, hedef uygulamanın Cmd+V'yi eksiksiz işlemesi için
///   güvenli bir süre (500ms) beklenip ardından eski içerik geri yüklenir.
public class TextInjector {
    public static let shared = TextInjector()

    private let queue = DispatchQueue(label: "com.voicetyping.textinjector", qos: .userInteractive)

    // nspasteboard.org topluluk standardı geçici pano tipleri (Raycast, Maccy, Alfred vb. için)
    public static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    public static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

    private init() {}

    public func getClipboard() -> String {
        return NSPasteboard.general.string(forType: .string) ?? ""
    }

    @discardableResult
    public func setClipboard(_ text: String) -> Bool {
        let pb = NSPasteboard.general
        pb.clearContents()
        return pb.setString(text, forType: .string)
    }

    /// Panodaki tüm öğeleri ve formatları (metin, resim, dosya URL, RTF) tam sadakatle kopyalar.
    public func captureClipboardSnapshot() -> [NSPasteboardItem] {
        let pb = NSPasteboard.general
        guard let items = pb.pasteboardItems, !items.isEmpty else { return [] }

        var snapshot: [NSPasteboardItem] = []
        for item in items {
            let copy = NSPasteboardItem()
            for type in item.types {
                if let data = item.data(forType: type) {
                    copy.setData(data, forType: type)
                }
            }
            snapshot.append(copy)
        }
        return snapshot
    }

    /// Alınan tam sadakatli panoyu NSPasteboard.general'a geri yükler.
    /// Boş bir snapshot da geçerli bir durumdur: kullanıcının panosu boşsa
    /// dikte metni bırakılmamalı, işlem sonunda pano yeniden boşaltılmalıdır.
    @discardableResult
    public func restoreClipboardSnapshot(_ snapshot: [NSPasteboardItem]) -> Bool {
        let pb = NSPasteboard.general
        pb.clearContents()
        guard !snapshot.isEmpty else { return true }
        return pb.writeObjects(snapshot)
    }

    /// Aktif (ASCII yazabilen) klavye düzeninde "v" karakterini üreten fiziksel tuş.
    /// Sanal tuş kodu fiziksel konumdur: Türkçe-F düzeninde ANSI V konumu "c"
    /// yazar, dolayısıyla sabit 0x09 kodu Cmd+V yerine Cmd+C gönderir. Dvorak ve
    /// benzeri düzenler de aynı sorundan etkilenir. TIS API'leri ana thread ister.
    public static func keyCodeForCharacter(_ character: String, fallback: CGKeyCode) -> CGKeyCode {
        guard let source = TISCopyCurrentASCIICapableKeyboardLayoutInputSource()?.takeRetainedValue(),
              let layoutPtr = TISGetInputSourceProperty(source, kTISPropertyUnicodeKeyLayoutData) else {
            return fallback
        }
        let layoutData = Unmanaged<CFData>.fromOpaque(layoutPtr).takeUnretainedValue() as Data
        let target = character.lowercased()

        return layoutData.withUnsafeBytes { raw -> CGKeyCode in
            guard let layout = raw.baseAddress?.assumingMemoryBound(to: UCKeyboardLayout.self) else { return fallback }
            for keyCode in 0..<128 {
                var deadKeyState: UInt32 = 0
                var chars = [UniChar](repeating: 0, count: 4)
                var length = 0
                let status = UCKeyTranslate(
                    layout,
                    UInt16(keyCode),
                    UInt16(kUCKeyActionDown),
                    0,
                    UInt32(LMGetKbdType()),
                    OptionBits(kUCKeyTranslateNoDeadKeysBit),
                    &deadKeyState,
                    chars.count,
                    &length,
                    &chars
                )
                if status == noErr, length > 0,
                   String(utf16CodeUnits: chars, count: length) == target {
                    return CGKeyCode(keyCode)
                }
            }
            return fallback
        }
    }

    /// macOS'ta donanım seviyesinde en güvenilir Cmd + V simülasyonu.
    /// Event tap üzerinden aktif pencereye tek ve temiz bir Cmd + V sinyali gönderir.
    public func simulateCmdV(vKeyCode: CGKeyCode = 0x09) {
        let source = CGEventSource(stateID: .combinedSessionState)

        guard let eventDown = CGEvent(keyboardEventSource: source, virtualKey: vKeyCode, keyDown: true),
              let eventUp = CGEvent(keyboardEventSource: source, virtualKey: vKeyCode, keyDown: false) else {
            // Yedek AppleScript yöntemi
            let script = "tell application \"System Events\" to keystroke \"v\" using command down"
            if let appleScript = NSAppleScript(source: script) {
                var error: NSDictionary?
                appleScript.executeAndReturnError(&error)
            }
            return
        }

        eventDown.flags = .maskCommand
        eventUp.flags = .maskCommand

        let tapLocation: CGEventTapLocation = AXIsProcessTrusted() ? .cghidEventTap : .cgSessionEventTap
        eventDown.post(tap: tapLocation)
        Thread.sleep(forTimeInterval: 0.025)
        eventUp.post(tap: tapLocation)
    }

    /// Belirtilen sanal tuş kodunu ve tuş bayraklarını simüle eder (örn: Return, Tab, Cmd+Return)
    public func simulateKeyPress(virtualKey: CGKeyCode, flags: CGEventFlags = []) {
        let source = CGEventSource(stateID: .combinedSessionState)
        guard let eventDown = CGEvent(keyboardEventSource: source, virtualKey: virtualKey, keyDown: true),
              let eventUp = CGEvent(keyboardEventSource: source, virtualKey: virtualKey, keyDown: false) else {
            return
        }

        if !flags.isEmpty {
            eventDown.flags = flags
            eventUp.flags = flags
        }

        let tapLocation: CGEventTapLocation = AXIsProcessTrusted() ? .cghidEventTap : .cgSessionEventTap
        eventDown.post(tap: tapLocation)
        Thread.sleep(forTimeInterval: 0.020)
        eventUp.post(tap: tapLocation)
    }

    /// Otomatik gönderim (Auto-Submit) için istenen tuşu tetikler
    public func triggerAutoSubmit(key: String) {
        let k = key.lowercased().trimmingCharacters(in: .whitespaces)
        switch k {
        case "cmd_return", "cmd+return", "command_return":
            simulateKeyPress(virtualKey: 36, flags: .maskCommand)
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Cmd + Return (⌘⏎)")
        case "shift_return", "shift+return":
            simulateKeyPress(virtualKey: 36, flags: .maskShift)
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Shift + Return (⇧⏎)")
        case "tab":
            simulateKeyPress(virtualKey: 48, flags: [])
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Tab (⇥)")
        default: // "return", "enter"
            simulateKeyPress(virtualKey: 36, flags: [])
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Return (⏎)")
        }
    }

    /// Yapıştırmanın gerçek sonucu. `sent` true dönse bile metin hedefe
    /// girmemiş olabilir; kesin sonuç bu değerle bildirilir.
    public enum InjectionOutcome: Equatable {
        /// Alan içeriği değişti: metin hedefe girdi.
        case verified
        /// Cmd+V gönderildi ama alan içeriği okunamıyor (bazı editörler/terminaller).
        case unverifiable
        /// Alan okunabiliyor ve değişmedi: yapıştırma olmadı. Metin panoda.
        case notInserted
        /// Kayıt sırasında sekme/uygulama değişti; yanlış yere yapıştırılmadı. Metin panoda.
        case targetChanged(reason: String)
    }

    /// Odaktaki alanın karşılaştırılabilir içerik izi.
    struct FieldSnapshot: Equatable {
        let value: String?
        let count: Int?
        var isReadable: Bool { value != nil || count != nil }
    }

    static func snapshot(of element: AXUIElement?) -> FieldSnapshot {
        guard let element else { return FieldSnapshot(value: nil, count: nil) }
        var valueRef: CFTypeRef?
        var value: String?
        if AXUIElementCopyAttributeValue(element, kAXValueAttribute as CFString, &valueRef) == .success {
            value = valueRef as? String
        }
        var countRef: CFTypeRef?
        var count: Int?
        if AXUIElementCopyAttributeValue(element, kAXNumberOfCharactersAttribute as CFString, &countRef) == .success {
            count = (countRef as? NSNumber)?.intValue
        }
        return FieldSnapshot(value: value, count: count)
    }

    /// Sonucu tahmin etmek yerine alanın içeriği değişti mi diye bakar.
    static func outcome(before: FieldSnapshot, after: FieldSnapshot) -> InjectionOutcome {
        guard before.isReadable, after.isReadable else { return .unverifiable }
        if let a = before.value, let b = after.value { return a == b ? .notInserted : .verified }
        if let a = before.count, let b = after.count { return a == b ? .notInserted : .verified }
        return .unverifiable
    }

    /// Metni kullanıcının elle yapıştırabileceği şekilde panoya koyar
    /// (geçici etiket olmadan; pano yöneticileri de görür).
    private func leaveOnClipboard(_ text: String) {
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.setString(text, forType: .string)
    }

    /// Dikte edilen metni hedef alana yapıştırır.
    ///
    /// 1. Hedef arka plandaysa öne getirilir.
    /// 2. **Doğrulama:** odaktaki alan kayıt başındaki hedef değilse (başka
    ///    sekme/uygulama) körlemesine yapıştırılmaz; metin panoya bırakılır.
    /// 3. Cmd+V gönderilir ve alan içeriği değişene kadar kısa süre izlenir.
    /// 4. Değişmediyse otomatik gönderim ve pano geri yüklemesi yapılmaz;
    ///    metin panoda kalır ve `completion(.notInserted)` bildirilir.
    ///
    /// Dönüş değeri yalnızca işlemin başlatılıp başlatılmadığıdır; kesin
    /// sonuç `completion` ile ana thread'de gelir.
    @discardableResult
    public func paste(
        text: String,
        targetContext: TargetContext? = nil,
        restoreClipboard: Bool = false,
        pasteDelayMs: Int = 20,
        autoSubmit: Bool = false,
        autoSubmitKey: String = "return",
        typeDirectly: Bool = false,
        completion: ((InjectionOutcome) -> Void)? = nil
    ) -> Bool {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
        let finish: (InjectionOutcome) -> Void = { outcome in
            DispatchQueue.main.async { completion?(outcome) }
        }

        // 1. Hedef Bağlam ve Arka Plandan Kurtarma (Smart Target Restoration)
        if let target = targetContext {
            let isFrontmost = (NSWorkspace.shared.frontmostApplication?.processIdentifier == target.pid)
            if !isFrontmost {
                print("[TextInjector] 🔄 Hedef (\(target.appName) [PID: \(target.pid)]) arka planda kalmış. Öne çağrılıp odak kurtarılıyor...")
                TargetInputManager.shared.restoreTargetFocus(to: target)
            }

            // 2. Hedef doğrulama: yanlış sekmeye/uygulamaya yapıştırma.
            if case let .changed(reason) = TargetInputManager.shared.verify(target) {
                print("[TextInjector] 🛑 Hedef değişti (\(reason)); yapıştırılmadı, metin panoya bırakıldı.")
                leaveOnClipboard(text)
                finish(.targetChanged(reason: reason))
                return true
            }
        }

        // Güvenli Giriş Teşhisi (Secure Event Input Check)
        if SecureInputDiagnostics.isSecureInputActive() {
            print("[TextInjector] ⚠️ Güvenli Giriş (Secure Event Input) devrede. Sistem parola alanında olabilir, sentetik Cmd+V kısıtlanabilir.")
        }

        let field = TargetInputManager.shared.focusedElement()
        let before = Self.snapshot(of: field)

        // 3. Doğrudan alana yazma → karakter olarak yazma → pano + Cmd+V.
        guard typeDirectly else {
            return pasteViaClipboard(
                text: text, restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
                autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
                field: field, before: before, finish: finish
            )
        }
        insertWithoutInputMethod(
            text: text, target: targetContext, typeDirectly: typeDirectly,
            restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
            autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
            field: field, before: before, finish: finish
        )
        return true
    }

    // MARK: - Panosuz yazma yöntemleri

    /// Sırayla dener, her adımda alanın gerçekten değiştiğini doğrular:
    /// 1. Doğrudan alana yazma (AX `kAXSelectedText`) — yalnızca Mac'in kendi
    ///    uygulamalarında; web/Electron alanlarında JS olayları tetiklenmediği
    ///    için sayfa metni "görmeyebilir", orada kullanılmaz.
    /// 2. Karakter olarak yazma (Unicode klavye olayları) — her yerde çalışır,
    ///    klavye düzeninden bağımsızdır.
    /// 3. Pano + Cmd+V — son çare.
    private func insertWithoutInputMethod(
        text: String,
        target: TargetContext?,
        typeDirectly: Bool,
        restoreClipboard: Bool,
        pasteDelayMs: Int,
        autoSubmit: Bool,
        autoSubmitKey: String,
        field: AXUIElement?,
        before: FieldSnapshot,
        finish: @escaping (InjectionOutcome) -> Void
    ) {
        queue.async { [weak self] in
            guard let self else { return }
            let succeed: (InjectionOutcome, String) -> Void = { outcome, method in
                print("[TextInjector] ✍️ Metin \(method) ile yazıldı (\(outcome)).")
                if autoSubmit {
                    Thread.sleep(forTimeInterval: 0.080)
                    self.triggerAutoSubmit(key: autoSubmitKey)
                }
                finish(outcome)
            }

            if typeDirectly, let field, Self.canInsertViaAccessibility(target: target, before: before),
               AXUIElementSetAttributeValue(field, kAXSelectedTextAttribute as CFString, text as CFString) == .success {
                let outcome = Self.waitForChange(field: field, before: before)
                if outcome == .verified { return succeed(outcome, "doğrudan alana yazma") }
                print("[TextInjector] ↩️ Doğrudan yazma alanı değiştirmedi; karakter olarak yazılacak.")
            }

            if typeDirectly, Self.canTypeAsCharacters(text) {
                self.typeCharacters(text)
                let outcome = Self.waitForChange(field: field, before: before)
                if outcome != .notInserted { return succeed(outcome, "karakter olarak yazma") }
                print("[TextInjector] ↩️ Karakter olarak yazma alanı değiştirmedi; Cmd+V deneniyor.")
            }

            DispatchQueue.main.async {
                _ = self.pasteViaClipboard(
                    text: text, restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
                    autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
                    field: field, before: before, finish: finish
                )
            }
        }
    }

    /// Doğrudan alana yazma yalnızca içeriği okunabilen (sonucu doğrulanabilen)
    /// Mac uygulaması alanlarında kullanılır.
    static func canInsertViaAccessibility(target: TargetContext?, before: FieldSnapshot) -> Bool {
        guard before.value != nil else { return false }
        guard let target else { return false }
        if target.pageURL != nil { return false }
        let category = AppProfileFormatter.shared.detectCategory(
            bundleIdentifier: target.bundleIdentifier, appName: target.appName
        )
        if category == .terminal || category == .codeEditor { return false }
        let webHosts: Set<String> = [
            "com.google.Chrome", "com.apple.Safari", "company.thebrowser.Browser", "com.brave.Browser",
            "org.mozilla.firefox", "com.microsoft.edgemac", "com.operasoftware.Opera",
            "com.tinyspeck.slackmacgap", "com.hnc.Discord", "notion.id", "net.whatsapp.WhatsApp",
        ]
        return !webHosts.contains(target.bundleIdentifier)
    }

    /// Satır sonu ve sekme karakterleri tuş olarak gönderilirse sohbet
    /// uygulamalarında mesajı erkenden gönderebilir veya odağı taşıyabilir;
    /// bu metinler pano yoluna bırakılır.
    static func canTypeAsCharacters(_ text: String) -> Bool {
        !text.isEmpty && text.count <= 4000 && !text.contains(where: { $0 == "\n" || $0 == "\r" || $0 == "\t" })
    }

    /// Metni Unicode klavye olayları olarak gönderir (20 UTF-16 birimlik parçalar).
    /// Tuş kodu değil karakter taşıdığı için klavye düzeninden etkilenmez; basılı
    /// kalmış değiştirici tuşlar araya girmesin diye bayraklar temizlenir.
    func typeCharacters(_ text: String) {
        let source = CGEventSource(stateID: .combinedSessionState)
        let tap: CGEventTapLocation = AXIsProcessTrusted() ? .cghidEventTap : .cgSessionEventTap
        var chunk: [UniChar] = []

        func flush() {
            guard !chunk.isEmpty,
                  let down = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: true),
                  let up = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: false) else { return }
            down.flags = []
            up.flags = []
            chunk.withUnsafeBufferPointer { buffer in
                down.keyboardSetUnicodeString(stringLength: buffer.count, unicodeString: buffer.baseAddress)
                up.keyboardSetUnicodeString(stringLength: buffer.count, unicodeString: buffer.baseAddress)
            }
            down.post(tap: tap)
            up.post(tap: tap)
            chunk.removeAll(keepingCapacity: true)
            usleep(4_000)
        }

        // Karakter sınırında böl: emoji ve birleşik harfler parçalanmaz.
        for character in text {
            let units = Array(String(character).utf16)
            if chunk.count + units.count > 20 { flush() }
            chunk.append(contentsOf: units)
        }
        flush()
    }

    /// Alan içeriği değişene kadar en fazla ~450 ms izler.
    static func waitForChange(field: AXUIElement?, before: FieldSnapshot) -> InjectionOutcome {
        guard before.isReadable else { return .unverifiable }
        // Sık ama kısa aralıklarla bak: başarı ~25 ms'de fark edilir, üst sınır ~450 ms.
        var result = InjectionOutcome.notInserted
        for _ in 0..<18 {
            Thread.sleep(forTimeInterval: 0.025)
            result = outcome(before: before, after: snapshot(of: field))
            if result != .notInserted { break }
        }
        return result
    }

    private func pasteViaClipboard(
        text: String,
        restoreClipboard: Bool,
        pasteDelayMs: Int,
        autoSubmit: Bool,
        autoSubmitKey: String,
        field: AXUIElement?,
        before: FieldSnapshot,
        finish: @escaping (InjectionOutcome) -> Void
    ) -> Bool {
        let pb = NSPasteboard.general
        let snapshot = restoreClipboard ? captureClipboardSnapshot() : []
        let vKeyCode = Self.keyCodeForCharacter("v", fallback: 0x09)

        // Pano yazımı başarısızsa sentetik Cmd+V göndermek yanlış başarı hissi verir.
        pb.clearContents()
        guard pb.setString(text, forType: .string) else {
            print("[TextInjector] ❌ Metin panoya yazılamadı.")
            return false
        }
        _ = pb.setData(Data(), forType: Self.transientType)
        _ = pb.setData(Data(), forType: Self.autoGeneratedType)

        queue.async { [weak self] in
            guard let self = self else { return }

            if pasteDelayMs > 0 {
                Thread.sleep(forTimeInterval: Double(pasteDelayMs) / 1000.0)
            }

            self.simulateCmdV(vKeyCode: vKeyCode)

            // 4. Sonuç doğrulama: alan içeriği değişti mi?
            let outcome = Self.waitForChange(field: field, before: before)

            if outcome == .notInserted {
                // Metin hedefe girmedi: Enter gönderme, eski panoyu geri yükleme.
                print("[TextInjector] ❌ Yapıştırma doğrulanamadı: alan değişmedi. Metin panoda bırakıldı.")
                DispatchQueue.main.async { self.leaveOnClipboard(text) }
                finish(.notInserted)
                return
            }

            if autoSubmit {
                Thread.sleep(forTimeInterval: 0.080)
                self.triggerAutoSubmit(key: autoSubmitKey)
            }

            finish(outcome)

            // Eski panoyu geri yükle; kullanıcı arada yeni bir şey kopyaladıysa ezme.
            if restoreClipboard {
                Thread.sleep(forTimeInterval: 0.50)
                DispatchQueue.main.async {
                    let currentText = NSPasteboard.general.string(forType: .string)
                    if currentText == text {
                        _ = self.restoreClipboardSnapshot(snapshot)
                    } else {
                        print("[TextInjector] 🛡️ Pano içeriği değiştiği için eski pano geri yüklemesi iptal edildi (kullanıcının yeni kopyalaması korundu).")
                    }
                }
            }
        }

        return true
    }

    /// inject metodu
    @discardableResult
    public func inject(
        text: String,
        targetContext: TargetContext? = nil,
        pasteDelayMs: Int = 20,
        completion: ((InjectionOutcome) -> Void)? = nil
    ) -> Bool {
        let config = ConfigManager.shared.config
        return paste(
            text: text,
            targetContext: targetContext,
            restoreClipboard: config.restore_clipboard,
            pasteDelayMs: pasteDelayMs,
            autoSubmit: config.enable_auto_submit,
            autoSubmitKey: config.auto_submit_key,
            typeDirectly: config.type_text_directly,
            completion: completion
        )
    }
}


